"""Writes database/schema.sql from app/collections.py.  python scripts/gen_schema.py"""
import pathlib
import sys

sys.path.insert(0, str(pathlib.Path(__file__).resolve().parents[1]))
from app.collections import COLLS  # noqa: E402

TYPES = {"str": "VARCHAR(255) NULL", "date": "DATE NULL", "month": "CHAR(7) NULL"}
TAIL = "ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci"

out = [
    "-- PeopleDesk HR: MySQL 8.0+ schema (also runs on MariaDB 10.5+).",
    "-- Generated by backend/scripts/gen_schema.py from backend/app/collections.py.",
    "-- Every business record is stored whole in `data` (JSON); the other columns are",
    "-- indexed copies of fields the server filters and checks permissions on.",
    "",
    "CREATE DATABASE IF NOT EXISTS peopledesk CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;",
    "USE peopledesk;",
    "",
    "-- Group name, app settings, statutory parameters, number sequences",
    "CREATE TABLE IF NOT EXISTS app_kv (",
    "  k          VARCHAR(32)  NOT NULL PRIMARY KEY,",
    "  data       JSON         NOT NULL,",
    "  updated_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3)",
    f") {TAIL};",
    "",
    "-- Bumped on every save so open browsers know to reload",
    "CREATE TABLE IF NOT EXISTS app_meta (",
    "  id  TINYINT NOT NULL PRIMARY KEY,",
    "  rev BIGINT  NOT NULL DEFAULT 0",
    f") {TAIL};",
    "INSERT IGNORE INTO app_meta (id, rev) VALUES (1, 0);",
    "",
]

for c in COLLS:
    cols = [
        "  id         VARCHAR(64)  NOT NULL PRIMARY KEY,",
        "  company_id VARCHAR(64)  NULL,",
        "  emp_id     VARCHAR(64)  NULL,",
    ]
    keys = ["  KEY ix_company (company_id)", "  KEY ix_emp (emp_id)"]
    for col, (_k, kind) in c.extra.items():
        cols.append(f"  {col:<10} {TYPES[kind]},")
        keys.append(f"  KEY ix_{col} ({col})")
    cols += [
        "  data       JSON         NOT NULL,",
        "  created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),",
        "  updated_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),",
        "  updated_by VARCHAR(64)  NULL,",
    ]
    out.append(f"-- state.{c.name}")
    out.append(f"CREATE TABLE IF NOT EXISTS {c.table} (")
    out += cols
    out.append(",\n".join(keys))
    out.append(f") {TAIL};")
    out.append("")

out += [
    "-- Shift roster: one row per employee per day (shift id, or WO for a rostered weekly off)",
    "CREATE TABLE IF NOT EXISTS roster (",
    "  emp_id     VARCHAR(64)  NOT NULL,",
    "  day        DATE         NOT NULL,",
    "  value      VARCHAR(64)  NOT NULL,",
    "  updated_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),",
    "  PRIMARY KEY (emp_id, day),",
    "  KEY ix_day (day)",
    f") {TAIL};",
    "",
    "-- Activity log (append-only; the server stamps who did it)",
    "CREATE TABLE IF NOT EXISTS audit_log (",
    "  id      VARCHAR(64)   NOT NULL PRIMARY KEY,",
    "  at      BIGINT        NOT NULL,",
    "  by_emp  VARCHAR(64)   NULL,",
    "  what    VARCHAR(255)  NOT NULL,",
    "  detail  VARCHAR(1000) NULL,",
    "  module  VARCHAR(32)   NULL,",
    "  ref_type VARCHAR(32)  NULL,",
    "  ref_id  VARCHAR(64)   NULL,",
    "  KEY ix_ref (ref_type, ref_id),",
    "  KEY ix_at (at),",
    "  KEY ix_by (by_emp)",
    f") {TAIL};",
    "",
    "-- Uploaded files (expense receipts and similar), stored on disk",
    "CREATE TABLE IF NOT EXISTS files (",
    "  id          VARCHAR(64)  NOT NULL PRIMARY KEY,",
    "  name        VARCHAR(255) NOT NULL,",
    "  mime        VARCHAR(128) NULL,",
    "  size        BIGINT       NULL,",
    "  path        VARCHAR(512) NOT NULL,",
    "  company_id  VARCHAR(64)  NULL,",
    "  owner_emp   VARCHAR(64)  NULL,",
    "  created_at  BIGINT       NOT NULL",
    f") {TAIL};",
    "",
    "-- Letter numbers for generated documents: one counter per document-type prefix, company and financial year",
    "CREATE TABLE IF NOT EXISTS doc_counters (",
    "  k  VARCHAR(128) NOT NULL PRIMARY KEY,",
    "  n  INT          NOT NULL DEFAULT 0",
    f") {TAIL};",
    "",
    "-- Sign-in secrets live here, never in employees.data",
    "CREATE TABLE IF NOT EXISTS auth_credentials (",
    "  employee_id VARCHAR(64)  NOT NULL PRIMARY KEY,",
    "  pw_hash     VARCHAR(100) NULL,",
    "  google_sub  VARCHAR(64)  NULL,",
    "  updated_at  TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),",
    "  UNIQUE KEY ux_google_sub (google_sub),",
    "  CONSTRAINT fk_auth_emp FOREIGN KEY (employee_id) REFERENCES employees (id) ON DELETE CASCADE",
    f") {TAIL};",
    "",
]

dest = pathlib.Path(__file__).resolve().parents[2] / "database" / "schema.sql"
dest.write_text("\n".join(out))
print(f"wrote {dest}")
